#!/usr/bin/env python3
"""배치별 GPT 이미지 생성 프롬프트를 art/npc/prompts/<배치>.md 로 만듭니다.  python3 tools/npc_batch_prompt.py"""
import json,os
root=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
man=json.load(open(os.path.join(root,'art/npc/NPC_MANIFEST.json'),encoding='utf-8'));npcs={n['npc_id']:n for n in man['npcs']}
PROP={'mayor':'town chain of office, sash, walking cane','castellan':'castle crest tabard, keys, short cape','harbor_master':'captain coat, brass spyglass, rope','grocer':'apron, basket of fruit','innkeeper':'apron, tray with a mug','guard':'helmet, short spear, town tabard','child':'oversized cap or hair ribbon, small toy','courier':'messenger bag, rolled letters, quick-travel boots','miller':'flour-dusted apron, sack of grain','baker':'tall baker hat, bread peel, apron','gardener':'straw hat, watering can','shepherd':'hooked staff, wool scarf','waiter':'vest, napkin on arm, tray','fisher':'fishing rod, bucket, waders','cook':'cook hat, ladle','farmer':'straw hat, pitchfork or hoe','clockmaker':'magnifier on head, pocket watch, vest','tailor':'tape measure on neck, pin cushion, scissors','party_planner':'party hat, streamers, clipboard','boatman':'oar, striped shirt, cap','carpenter':'tool belt, hammer, saw','engineer':'goggles, wrench, overalls','healer':'white robe, herb pouch, small staff','cart_driver':'driver cap, reins, gloves','scout':'hooded cloak, spyglass, quiver','woodworker':'apron, chisel, wood shavings','archivist':'round glasses, ledger, ink stained fingers','dockworker':'rolled sleeves, rope, crate','letter_keeper':'sealed envelopes, stamp, cap','water_seller':'water jugs on a carrying pole, light robes','guide':'travel hat, flag or lantern, map','mapmaker':'map scrolls, compass, drafting pen','bell_keeper':'hand bell, bell-embroidered tunic','archaeologist':'brush, pith hat, satchel','scribe':'quill, scroll, ink pot','bird_keeper':'bird on shoulder, perch glove','letter_writer':'quill, stationery, ink','weaver':'shuttle, colorful yarn, shawl','race_judge':'flag, whistle, stopwatch','coach':'whistle, tracksuit jacket, clipboard','medal_maker':'medals on a ribbon rack, small hammer','lost_property_clerk':'tagged items, ledger, name tags','umbrella_maker':'umbrellas, rain cape','bookbinder':'needle and thread, book press, apron','navigator':'sextant, sea chart, captain cap','shipwright':'plank, mallet, leather apron','lighthouse_keeper':'lantern, thick coat, beacon badge','travel_agent':'ticket roll, suitcase sticker, neat vest','tutor':'book, chalk, glasses','equipment_maker':'backpack frame, rope coil, tool apron','forester':'axe, green cloak, leaf badge','herbalist':'herb bundles, mortar, apron','bell_maker':'bell mold, tongs, apron','stage_manager':'headset or clipboard, black clothes, lantern','musician':'small lute or flute, bright vest','decor_maker':'ribbons, flowers, scissors','seal_keeper':'wax stick, seal stamp, candle','messenger':'sealed scroll case, travel cloak','translator':'two books, speech-bubble badge, glasses','locksmith':'giant ring of keys, goggles','historian':'thick book, scroll case, glasses','stoneworker':'chisel, hammer, dusty apron','granny':'shawl, cane, bun hairstyle','grandpa':'walking stick, white mustache, vest','postman':'postman cap, mail bag','foreman':'hard hat, blueprints, vest','runner':'headband, running shoes, number cloth','captain':'guard captain armor, plume, cape','ranger':'green cloak, bow, leaf hat','librarian':'glasses, book stack, cardigan','mechanic':'goggles, wrench, oil-stained overalls','hunter':'hood, bow, fur trim','traveler':'big backpack, bedroll, walking stick','cleaner':'broom, bucket, headscarf','landlord':'key ring, ledger, tidy coat','student':'satchel, notebook, school uniform','gourmet':'napkin tucked in collar, round belly, fork','merchant':'big bag of wares, trader hat, scales','teacher':'pointer stick, books, glasses','walker':'light hiking clothes, walking stick, cap','falconer':'falcon on leather glove, feathered cap','bookseller':'stack of books, apron, glasses','fruit_seller':'basket of fruit, apron','sailor':'striped shirt, bandana, rope','swimmer':'swim cap, towel, goggles','linguist':'books, speech-bubble pin, glasses','chess_master':'chess board, tidy coat','birdwatcher':'binoculars, notebook, hat with feather','mother':'apron, hair tied, basket','chef':'tall chef hat, ladle, apron','florist':'flower basket, apron with floral pattern','park_keeper':'cap, broom, ring of keys','detective':'long coat, magnifier, hat','officer':'police-style cap, baton, badge','artist':'beret, paint brush, palette','boy':'cap, short pants, small satchel','girl':'ribbons, skirt, small bag','cat_butler':'neat dress, small cat on shoulder or arms','dog_owner':'leash, small dog beside him (draw the dog as a separate small part of the same sprite)'}
ST="""Style: warm colors, thick dark outlines, detailed 16-bit chibi pixel art, big head and small body, slightly top-down RPG view. Match the existing Grammar Saga hero/NPC art exactly. Real alpha-transparent PNG. No background, no checkerboard, no text, no numbers, no grid lines, no shadows on the ground."""
def desc(n):
    ag={'child':'child (about 80px tall)','teen':'teenager','adult':'adult (about 100px tall)','elder':'elderly adult'}[n['age']]
    g={'f':'female','m':'male','any':'gender your choice, but make the character clearly individual'}[n['gender']]
    return f"**{n['npc_id']}** — {n['name_en']}{' ('+n['name_ko']+')' if n['name_ko'] else ''}: {n['profession'].replace('_',' ')}, {ag}, {g}. Region look: {n['region_style']}. Props: {PROP.get(n['profession'],'profession-appropriate props')}."
os.makedirs(os.path.join(root,'art/npc/prompts'),exist_ok=True)
for b in man['batches']:
    L=[f"# 배치 {b['batch']} ({'이동형 걷기 시트' if b['kind']=='mobile' else '고정형 정면 1컷'})",'']
    if b['kind']=='mobile':
        L+=["## 출력 규격",'- 이미지 1장: **1024×1024**, 투명 배경. 위쪽 절반(1024×512)=첫 번째 캐릭터, 아래쪽 절반=두 번째 캐릭터.','- 각 시트는 **8열×4행**, 칸 128×128. 행 순서: 1행 아래(정면), 2행 왼쪽, 3행 오른쪽, 4행 위(뒷모습). 한 행의 8프레임은 걷기 한 주기(왼발-중간-기본-중간-오른발-중간…, 3번째 칸이 가만히 선 기본 자세).','- 모든 칸에서 같은 얼굴·옷·소품·비율, **발 위치 y=116 고정**, 성인 높이 약 100px/어린이 80px, 칸 가장자리에서 2px 이상 띄우기.','- 이 파일은 시트 사이에 구분선, 이름표, 번호를 넣지 않습니다.','',ST,'','## 캐릭터']
    else:
        L+=["## 출력 규격",'- 이미지 1장: **1536×1024**, 투명 배경. **6열×4행(24칸), 칸 256×256**, 각 칸에 정면 전신 1컷(건물·가게 앞에 서 있는 모습). 도구가 128×128로 정확히 절반 축소합니다.','- 모든 캐릭터는 같은 크기 기준(성인 높이 약 200px, 어린이 160px), 발끝은 칸 아래에서 약 20px 위, 칸 가장자리에서 8px 이상 띄우기.','- 같은 직업이라도 서로 다른 사람처럼 머리·얼굴·체형·옷 색을 달리하되 직업 소품은 분명히.','',ST,'','## 캐릭터 (왼쪽 위에서 오른쪽으로, 위 행부터)']
    for i,nid in enumerate(b['npcs'],1):L.append(f"{i}. "+desc(npcs[nid]))
    L+=['','## 받은 뒤','`python3 tools/npc_slice_batch.py %s <받은_이미지.png>` 로 자르고 검사합니다. 불합격 목록만 다시 요청하세요.'%b['batch']]
    open(os.path.join(root,'art/npc/prompts/%s.md'%b['batch']),'w',encoding='utf-8').write('\n'.join(L)+'\n')
print(len(man['batches']),'개 프롬프트 생성')
